import React from 'react';
import { Button, Stack } from '@mui/material';
import { useLocation, useNavigate } from 'react-router-dom';
import { isViewRoleProfile } from '../../utils/authRole';

const ADMIN_NAV_ITEMS = [
  { label: 'Registry', path: '/admin/dashboard' },
  { label: 'Integrations', path: '/admin/integrations' },
  { label: 'Blog & articles', path: '/admin/blog-articles' },
  { label: 'Factor review', path: '/admin/emission-factors', adminOnly: true },
  { label: 'OCR benchmarks', path: '/admin/ocr-benchmarks', adminOnly: true },
  { label: 'OCR automation', path: '/admin/ocr-automation', adminOnly: true },
  { label: 'System health', path: '/admin/system-health', adminOnly: true },
];

const AdminInternalNav: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const isViewOnly = isViewRoleProfile();

  return (
    <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
      {ADMIN_NAV_ITEMS.filter((item) => !isViewOnly || !item.adminOnly).map((item) => (
        <Button
          key={item.path}
          size="small"
          variant={location.pathname === item.path ? 'contained' : 'outlined'}
          onClick={() => navigate(item.path)}
        >
          {item.label}
        </Button>
      ))}
    </Stack>
  );
};

export default AdminInternalNav;
